public void readFrom(final InputStream in) throws IOException {
    // Clear the buffer
    this.buffer = new byte[0];

    // Read from the input stream and fill the buffer
    int bytesRead = 0;
    byte[] buffer = new byte[1024];
    while ((bytesRead = in.read(buffer)) != -1) {
        this.buffer = Arrays.copyOf(this.buffer, this.buffer.length + bytesRead);
        System.arraycopy(buffer, 0, this.buffer, this.buffer.length - bytesRead, bytesRead);
    }

    // Reset the read pointer
    this.readPointer = 0;
}

