public ByteVector putInt(final int intValue) {
    // Automatically enlarge the byte vector if necessary
    if (this.data.length < this.w + 4) {
        byte[] newData = new byte[this.w + 4];
        System.arraycopy(this.data, 0, newData, 0, this.w);
        this.data = newData;
    }

    // Put the int value into the byte vector
    this.data[this.w++] = (byte) (intValue >>> 24);
    this.data[this.w++] = (byte) (intValue >>> 16);
    this.data[this.w++] = (byte) (intValue >>> 8);
    this.data[this.w++] = (byte) intValue;

    return this;
}

