public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Get the first character of the name
    char firstChar = buf.charAt(nameStart);

    // Check if the first character is a letter
    if (Character.isLetter(firstChar)) {
        // Append the first character to the buffer
        buf.append(firstChar);

        // Get the index of the next letter
        int nextLetterIndex = nameStart + 1;
        while (nextLetterIndex < buf.length() && !Character.isLetter(buf.charAt(nextLetterIndex))) {
            nextLetterIndex++;
        }

        // If there is a next letter, append it to the buffer
        if (nextLetterIndex < buf.length()) {
            buf.append(buf.charAt(nextLetterIndex));
        }
    }
}

