public static String applyRelativePath(String path, String relativePath) {
    // Check if the relative path is valid
    if (relativePath.startsWith("/")) {
        throw new IllegalArgumentException("Relative path cannot start with '/'");
    }

    // Check if the path is a file or a folder
    boolean isFile = path.endsWith("/");

    // Remove the trailing slash from the path if it is a folder
    if (isFile) {
        path = path.substring(0, path.length() - 1);
    }

    // Split the relative path into its components
    String[] components = relativePath.split("/");

    // Iterate over the components and apply them to the path
    for (String component : components) {
        if (component.equals(".")) {
            // Do nothing
        } else if (component.equals("..")) {
            // Go up one level
            path = path.substring(0, path.lastIndexOf("/"));
        } else {
            // Go down one level
            path += "/" + component;
        }
    }

    // Add the trailing slash if the original path was a folder
    if (isFile) {
        path += "/";
    }

    return path;
}

